--region import
---@type OverseaStoreMgr
local OverseaStoreMgr = import('Game.OverseaStore.OverseaStoreMgr'):GetInstance()
---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')
--endregion import

--region define
local UIModule = CS.Engine.UI.UIModule
local TimerModule = CS.Engine.Modules.TimerModule
--endregion define

--- from: Assets/BundleResources/Prefabs/OverseaMall/OverseaMallIndulgenceActivityDialog.prefab
---@class OverseaStoreCommonNode
---@field Env                           	OverseaStoreCommonNode                  
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field RefreshTimer                  	UnityEngine.RectTransform               
---@field TimerGroup                    	UnityEngine.RectTransform               
---@field Root                          	UnityEngine.RectTransform               
---@field EmptyNode                     	UnityEngine.RectTransform               
---@field LoopView                      	Engine.UI.AutoFixSizeListView               
local OverseaStoreCommonNode = Class("OverseaStoreCommonNode")

--region lifecycle
function OverseaStoreCommonNode:__init()
    self._storeType      = nil
    self._storeData      = {}
end

function OverseaStoreCommonNode:__delete()
    self._storeType      = nil
    self._storeData      = nil
end

function OverseaStoreCommonNode:Awake()
    self:InitHandler()
end

function OverseaStoreCommonNode:Start()

end

function OverseaStoreCommonNode:OnDestroy()
    self:StopTimer()
    Events.RemoveListener(Constants.EventNames.OVERSEA_STORE_REFRESH, self._refreshEvent)
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要
end
--endregion lifecycle

--region init
function OverseaStoreCommonNode:InitHandler()
    self._refreshEvent = Events.AddListener(Constants.EventNames.OVERSEA_STORE_REFRESH, Bind(self, self.RefreshEventHandler))
end

function OverseaStoreCommonNode:InitData()
    local storeData = OverseaStoreMgr:GetStoreDataByType(self:GetStoreType())
    self:SetStoreData(storeData)
    self:StartTimer()
    if storeData.nextRefreshLeftSeconds then
        self:RefreshCountdown()
    end
    CfUtils.SetActive(self.TimerGroup, storeData.nextRefreshLeftSeconds and true or false)
end
--endregion init

--region handler
---列表刷新
function OverseaStoreCommonNode:OnGetItemByIndex(cell, index)
    if index < 0 then return nil end
    
    local cellData = self:GetProducts()[index + 1]
    local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreCommonCell)
    if scr then
        scr:RefreshCell(self:GetStoreType(), cellData)
    end
    return cell
end

---定时器更新
function OverseaStoreCommonNode:OnUpdate()
    if self:GetRefreshSeconds() then
        self:RefreshCountdown()
        if tonumber(self:GetRefreshSeconds()) <= 0 then
            Events.Broadcast(Constants.EventNames.OVERSEA_STORE_HOME_REFRESH)
        end
    end

    for i, v in ipairs(self:GetProducts()) do
        local go = self.LoopView:GetShownItemByItemIndex(i - 1)
        if not isNull(go) then
            local scr = CfUtils.GetLuaScr(go, OverseaStoreConstants.ScrPath.OverseaStoreCommonCell)
            scr:UpdateTimeGroupText(v)
        end
    end

end

---刷新事件回调
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreCommonNode:RefreshEventHandler(storeType)
    if storeType ~= self:GetStoreType() then return end
    self:RefreshUI()
end
--endregion handler

--region public
---刷新
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreCommonNode:Refresh(storeType)
    self:SetStoreType(storeType)
    self:InitData()
    self:RefreshUI()
    self:CellAnimation()
end

---刷新货币栏
function OverseaStoreCommonNode:RefreshCurrencyBar()
    local currencyList = {Constants.Currency.FreeDiamondId}
    if OverseaStoreMgr:IsSecondaryCurrencyEnable() then
        table.insert(currencyList, 1, Constants.Currency.PayDiamondId)
    end
    CfUtils.RefreshTopGoods(currencyList)
end
--endregion public

--region private
---刷新UI
function OverseaStoreCommonNode:RefreshUI()
    self:RefreshListView()
end

---刷新列表
function OverseaStoreCommonNode:RefreshListView()
    local storeData = self:GetProducts()
    if not self.LoopView.mLoopListView.IsListViewInit then
        self.LoopView:InitListView(#storeData, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopView, #storeData)
        self.LoopView:MovePanelToItemIndex(0)
    end
end

---开启定时器
function OverseaStoreCommonNode:StartTimer()
    TimerModule.Instance:AddTimer(self:GetTimerName(), 0, 1, Bind(self, self.OnUpdate))
end

---停止定时器
function OverseaStoreCommonNode:StopTimer()
    TimerModule.Instance:RemoveTimer(self:GetTimerName())
end

---刷新倒计时
function OverseaStoreCommonNode:RefreshCountdown()
    local seconds = checkInt(self:GetRefreshSeconds())
    if seconds > 0 then
        local text = CfUtils.GetTimeHMS4(seconds)
        CfUtils.FillText(self.RefreshTimer, text)
    end
end

---Cell动画
function OverseaStoreCommonNode:CellAnimation()
    local storeData = self:GetProducts()
    for i, v in ipairs(storeData) do
        local cell = self.LoopView:GetShownItemByItemIndex(i - 1)
        if isNotNull(cell) then
            local scr = CfUtils.GetLuaScr(cell, OverseaStoreConstants.ScrPath.OverseaStoreCommonCell)
            scr:PlayAnimation()
        end
    end
end
--endregion private

--region get / set
---设置商店类型
function OverseaStoreCommonNode:SetStoreType(storeType)
    self._storeType = storeType
end

---获取商店类型
function OverseaStoreCommonNode:GetStoreType()
    return self._storeType
end

---设置充值数据
function OverseaStoreCommonNode:SetStoreData(storeData)
    self._storeData = checkTable(storeData)
end

---获取充值数据
function OverseaStoreCommonNode:GetStoreData()
    return self._storeData
end

---获取刷新时间
function OverseaStoreCommonNode:GetRefreshSeconds()
    return self:GetStoreData().nextRefreshLeftSeconds
end

---获取商品列表
function OverseaStoreCommonNode:GetProducts()
    return checkTable(self:GetStoreData().products)
end

---获取定时器名称
function OverseaStoreCommonNode:GetTimerName()
    return Constants.TimerName.OverseaStoreCommonNodeTimer .. self._storeType
end

--endregion get / set

return OverseaStoreCommonNode